    document.addEventListener('click', e => { 
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', e => { 
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    // Theme logic
    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme); // Start dark for poster

    // Number Counter Animation
    function animateCounters() {
      document.querySelectorAll('[data-count]').forEach(function(el) {
        if (el.dataset.counted) return;
        el.dataset.counted = '1';
        var target = parseFloat(el.dataset.count), prefix = el.dataset.prefix || '', suffix = el.dataset.suffix || '';
        var start = performance.now(), duration = 1200;
        (function tick(now) {
          var p = Math.min((now - start) / duration, 1), eased = 1 - Math.pow(1 - p, 3);
          el.textContent = prefix + (target * eased).toFixed(target % 1 === 0 ? 0 : 1) + suffix;
          if (p < 1) requestAnimationFrame(tick);
        })(start);
      });
    }
    document.addEventListener('DOMContentLoaded', function() {
      setTimeout(animateCounters, 1000); // Trigger since everything is visible
    });

    // Chart.js integration
    var chartsBuilt = false;

    function resetCanvas(id) {
      var old = document.getElementById(id);
      if (!old) return null;
      var parent = old.parentNode;
      var canvas = document.createElement('canvas');
      canvas.id = id;
      parent.replaceChild(canvas, old);
      return canvas;
    }

    function buildCharts() {
      if (chartsBuilt || typeof Chart === 'undefined') return;

      var isDark = document.documentElement.classList.contains('theme-dark');
      var s = getComputedStyle(document.documentElement);
      var textColor = s.getPropertyValue('--text').trim() || (isDark ? '#F8FAFC' : '#0F172A');
      var gridColor = isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)';
      var accent = s.getPropertyValue('--accent').trim() || '#EF4444';
      var accentSecondary = s.getPropertyValue('--accent-secondary').trim() || '#F59E0B';
      var textSecondary = s.getPropertyValue('--text-secondary').trim() || '#94A3B8';
      var positive = s.getPropertyValue('--positive').trim() || '#10B981';

      var ctx = resetCanvas('timelineChart');
      if (ctx) {
        // Generate approximate timeline data
        var labels = [];
        var trueBaseline = [];
        var ipccBaseline = [];
        var proxyData = [];
        var instrumentalData = [];

        for (var year = 1700; year <= 2020; year += 5) {
          labels.push(year);
          // True baseline is 0
          trueBaseline.push(0);
          // IPCC baseline is ~0.5 (1850-1900 average)
          ipccBaseline.push(0.5);

          // Smoothed synthetic proxy anomaly based on brief (reaches ~1.7 at 2020)
          var anomaly = 0;
          if (year < 1790) anomaly = (Math.random() * 0.1) - 0.05; // 0 mean
          else if (year < 1850) anomaly = 0.1 + ((year - 1790) / 60) * 0.3 + (Math.random() * 0.1);
          else if (year < 1900) anomaly = 0.4 + ((year - 1850) / 50) * 0.15 + (Math.random() * 0.1);
          else if (year < 1960) anomaly = 0.55 + ((year - 1900) / 60) * 0.3 + (Math.random() * 0.1);
          else anomaly = 0.85 + Math.pow((year - 1960) / 60, 2) * 0.85; // curves up to 1.7

          proxyData.push(anomaly);

          if (year >= 1850) {
            // Instrumental is systematically lower by ~0.5 compared to proxy's true baseline
            instrumentalData.push(anomaly - 0.5 + (Math.random() * 0.1 - 0.05));
          } else {
            instrumentalData.push(null);
          }
        }

        window.myChart = new Chart(ctx, {
          type: 'line',
          data: {
            labels: labels,
            datasets: [
              {
                label: 'Sclerosponge Proxy (True Pre-Industrial Baseline)',
                data: proxyData,
                borderColor: accentSecondary,
                backgroundColor: 'transparent',
                borderWidth: 4,
                pointRadius: 0,
                pointHoverRadius: 8,
                tension: 0.4
              },
              {
                label: 'Instrumental Record (IPCC 1850-1900 Baseline)',
                data: instrumentalData,
                borderColor: '#3b82f6',
                borderDash: [8, 4],
                backgroundColor: 'transparent',
                borderWidth: 3,
                pointRadius: 0,
                pointHoverRadius: 8,
                tension: 0.4
              }
            ]
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            animation: false,
            plugins: {
              tooltip: {
                enabled: true,
                padding: 16,
                cornerRadius: 8,
                titleFont: { size: 18, family: 'Inter' },
                bodyFont: { size: 16, family: 'Inter' }
              },
              legend: {
                position: 'top',
                labels: { color: textColor, font: { size: 18, family: 'Inter' }, padding: 30 }
              },
              annotation: {
                annotations: {
                  threshold15: {
                    type: 'line',
                    yMin: 1.5,
                    yMax: 1.5,
                    borderColor: accent,
                    borderWidth: 2,
                    borderDash: [6, 6],
                    label: {
                      enabled: true,
                      content: '1.5 °C Paris Agreement Threshold Exceeded',
                      position: 'end',
                      backgroundColor: accent,
                      color: '#fff',
                      font: { size: 16, family: 'Inter', weight: 'bold' }
                    }
                  },
                  baseline1700: {
                    type: 'line',
                    yMin: 0,
                    yMax: 0,
                    borderColor: positive,
                    borderWidth: 2,
                    borderDash: [4, 4],
                    label: {
                      enabled: true,
                      content: 'True Pre-Industrial Baseline (1700-1790)',
                      position: 'start',
                      backgroundColor: positive,
                      color: '#fff',
                      font: { size: 14, family: 'Inter' }
                    }
                  },
                  baseline1850: {
                    type: 'line',
                    yMin: 0.5,
                    yMax: 0.5,
                    borderColor: '#3b82f6',
                    borderWidth: 2,
                    borderDash: [4, 4],
                    label: {
                      enabled: true,
                      content: 'IPCC Baseline (1850-1900) - Already ~0.5°C warmer',
                      position: 'start',
                      backgroundColor: '#3b82f6',
                      color: '#fff',
                      font: { size: 14, family: 'Inter' }
                    }
                  }
                }
              }
            },
            scales: {
              x: {
                ticks: { color: textColor, font: { size: 16, family: 'Inter' } },
                grid: { color: gridColor },
                title: { display: true, text: 'Year', color: textSecondary, font: { size: 18, weight: 'bold' } }
              },
              y: {
                ticks: { color: textColor, font: { size: 16, family: 'Inter' }, stepSize: 0.5 },
                grid: { color: gridColor },
                title: { display: true, text: 'Temperature Anomaly (°C)', color: textSecondary, font: { size: 18, weight: 'bold' } }
              }
            },
            layout: { padding: { top: 20, right: 30, bottom: 20, left: 20 } }
          },
          plugins: [{
            id: 'customAnnotations',
            afterDraw: function(chart) {
              var ctx = chart.ctx;
              var yAxis = chart.scales.y;
              var xAxis = chart.scales.x;

              var y15 = yAxis.getPixelForValue(1.5);
              ctx.beginPath();
              ctx.moveTo(xAxis.left, y15);
              ctx.lineTo(xAxis.right, y15);
              ctx.strokeStyle = accent;
              ctx.lineWidth = 3;
              ctx.setLineDash([8, 8]);
              ctx.stroke();

              ctx.fillStyle = accent;
              ctx.font = 'bold 18px Inter';
              ctx.fillText('1.5 °C Paris Agreement Threshold', xAxis.right - 340, y15 - 15);

              var y0 = yAxis.getPixelForValue(0);
              ctx.beginPath();
              ctx.moveTo(xAxis.left, y0);
              ctx.lineTo(xAxis.right, y0);
              ctx.strokeStyle = positive;
              ctx.lineWidth = 2;
              ctx.setLineDash([4, 4]);
              ctx.stroke();

              ctx.fillStyle = positive;
              ctx.font = '600 16px Inter';
              ctx.fillText('True Pre-Industrial Baseline (1700-1790)', xAxis.left + 20, y0 - 10);

              var y05 = yAxis.getPixelForValue(0.5);
              ctx.beginPath();
              ctx.moveTo(xAxis.left, y05);
              ctx.lineTo(xAxis.right, y05);
              ctx.strokeStyle = '#3b82f6';
              ctx.lineWidth = 2;
              ctx.setLineDash([4, 4]);
              ctx.stroke();

              ctx.fillStyle = '#3b82f6';
              ctx.font = '600 16px Inter';
              ctx.fillText('IPCC Baseline (1850-1900) - Already ~0.5 °C warmer', xAxis.left + 20, y05 - 10);
            }
          }]
        });
      }
      chartsBuilt = true;
    }

    function onThemeChange() {
      chartsBuilt = false;
      setTimeout(buildCharts, 100);
    }

    document.addEventListener('DOMContentLoaded', buildCharts);
  </script>
</body>
